import {publicAttribution} from './public-links.mjs';
import {el,action,image,external,safeURL} from './guide-common.mjs';
let dialog,entries=[],position=0,previousFocus;
function prepare(){
 if(dialog)return;
 dialog=el('dialog','','quest-gallery-dialog');dialog.setAttribute('aria-label','Скриншоты задания');
 const bar=el('div','','gallery-toolbar');bar.append(el('strong','Скриншоты задания'));const close=action('×',()=>dialog.close(),'icon-button');close.setAttribute('aria-label','Закрыть просмотр');bar.append(close);
 const stage=el('div','','gallery-stage'),photo=el('img','','gallery-full');photo.alt='';photo.id='gallery-full';
 const previous=action('‹',()=>step(-1),'gallery-arrow'),next=action('›',()=>step(1),'gallery-arrow');previous.id='gallery-prev';next.id='gallery-next';previous.setAttribute('aria-label','Предыдущий скриншот');next.setAttribute('aria-label','Следующий скриншот');stage.append(previous,photo,next);
 const caption=el('p','','gallery-caption');caption.id='gallery-caption';const translation=el('div','','gallery-translation');translation.id='gallery-translation';translation.hidden=true;const source=el('div','','gallery-source');source.id='gallery-source';const status=el('p','','gallery-status');status.id='gallery-status';status.setAttribute('role','status');dialog.append(bar,stage,caption,translation,source,status);document.body.append(dialog);
 dialog.addEventListener('keydown',e=>{if(e.key==='ArrowLeft'){e.preventDefault();step(-1);}if(e.key==='ArrowRight'){e.preventDefault();step(1);}});dialog.addEventListener('close',()=>previousFocus?.focus?.());dialog.addEventListener('click',e=>{if(e.target===dialog)dialog.close();});
 let start;photo.addEventListener('touchstart',e=>{start=e.touches[0]?.clientX;},{passive:true});photo.addEventListener('touchend',e=>{const end=e.changedTouches[0]?.clientX;if(start!=null&&Math.abs(end-start)>45)step(end<start?1:-1);start=null;},{passive:true});
 photo.onerror=()=>{photo.hidden=true;status.textContent='Изображение не загрузилось. Можно открыть оригинал по ссылке ниже.';};photo.onload=()=>{photo.hidden=false;status.textContent='';};
}
function step(offset){position=(position+offset+entries.length)%entries.length;render();}
function render(){const current=entries[position],photo=document.getElementById('gallery-full');photo.hidden=false;photo.src=safeURL(current.fullUrl||current.url);photo.alt=current.caption||'Место выполнения задания';document.getElementById('gallery-caption').textContent=`${position+1} / ${entries.length} · ${current.caption||'Скриншот задания'}`;const translation=document.getElementById('gallery-translation');translation.hidden=!current.annotationRu;translation.replaceChildren();if(current.annotationRu)translation.append(el('strong',current.translationKind==='complete'?'Текст на изображении':current.translationKind==='condensed'?'Краткий перевод подписи':'Перевод подписи на изображении'),el('p',current.annotationRu));for(const id of ['gallery-prev','gallery-next'])document.getElementById(id).disabled=entries.length<2;const source=document.getElementById('gallery-source');source.replaceChildren(external('Оригинал изображения ↗',current.originalUrl||current.fullUrl||current.url));if(current.sourceUrl)source.append(external('Источник и описание ↗',current.sourceUrl));if(current.copySourceUrl)source.append(external('Опубликованная копия и атрибуция ↗',current.copySourceUrl));if(current.attribution)source.append(el('span',publicAttribution(current.attribution)));if(current.fileSourceUrl)source.append(external('Страница файла и права ↗',current.fileSourceUrl));if(current.license||current.rights)source.append(el('span',publicAttribution(current.license||current.rights)));if(current.localization)source.append(el('span',publicAttribution(current.localization)));if(current.archived)source.append(el('span','Архивная копия исходного изображения'));if(current.verification==='source-index')source.append(el('span','Доступность изображения не подтверждена.'));document.getElementById('gallery-status').textContent='';}
export function openGallery(images,index=0){if(!images?.length)return;prepare();entries=images;position=Math.max(0,Math.min(index,entries.length-1));previousFocus=document.activeElement;render();dialog.showModal();}
export function galleryBlock(images,{title='Скриншоты задания',compact=false,association='quest',contextTitle='',carousel=images}={}){const root=el('section','','quest-gallery');if(!images?.length)return root;root.append(el('h3',title));if(association==='quest')root.append(el('p','Материалы всего задания. Точную цель уточняйте по подписи к изображению.','gallery-context'));const grid=el('div','','gallery-grid'+(compact?' compact':''));for(const [index,entry] of images.entries()){const b=action('',()=>openGallery(carousel,Math.max(0,carousel.indexOf(entry))),'gallery-thumb');b.setAttribute('aria-label','Открыть: '+(entry.caption||'скриншот задания'));const fullCaption=entry.caption||`Скриншот ${index+1}`;let caption=fullCaption;if(compact){if(contextTitle&&caption.startsWith(contextTitle+':'))caption=caption.slice(contextTitle.length+1).trim();caption=caption.replace(/\s*[—–-]\s*изображение\s+\d+$/i,'');}b.append(image(entry.url,fullCaption),el('span',caption),el('small',`Фото ${index+1} из ${images.length}`,'gallery-thumb-index'));if(entry.annotationRu&&entry.translationKind!=='complete')b.append(el('span',entry.annotationRu,'gallery-annotation'));grid.append(b);}root.append(grid,el('p','Источники и права указаны в просмотре. Игровые изображения — Battlestate Games.','guide-footer-note'));return root;}
